/**
 * ZAPROJEKTOWANI SUITE v1.8.1
 * Front fixes: hero overflow, about team image, mobile CTA restore, contact card/tabs polish, logo sizing/hover.
 */

function zp_suite_upgrade_181_front_fixes(){
  $opts = get_option('zp_suite_options', []);
  if (!is_array($opts)) { $opts = []; }
  if (!isset($opts['header']) || !is_array($opts['header'])) { $opts['header'] = []; }

  // Keep user custom values, but upgrade the tiny previous defaults.
  // v1.8.74: logo sizing is controlled only by Header panel fields; old mobile logo migration disabled.
  // v1.8.74: logo X offset is controlled only by Header panel field; old migration disabled.

  update_option('zp_suite_options', $opts, false);
}

add_action('plugins_loaded', function(){
  if (get_option('zp_suite_front_fixes_181_done') !== '1') {
    zp_suite_upgrade_181_front_fixes();
    update_option('zp_suite_front_fixes_181_done', '1', false);
  }
}, 20);

